-- Test savollarining ruscha matni — 28-partiya: uch savoldan qolgan qahramonlar.
-- Imom at-Termiziy, Burhoniddin Marg'inoniy, Bahouddin Naqshband, Furqat,
-- Abdulla Qahhor, Chingiz Ahmarov, Ibroyim Yusupov.

-- ===== Imom at-Termiziy =====
UPDATE quiz_questions SET question_ru = 'В каком селении родился Имам ат-Термизи?', options_ru = '["В селении Буг", "В селении Афшона", "В селении Хартанг", "В селении Багистан"]'::jsonb, explanation_ru = 'Имам ат-Термизи родился в 209 году хиджры (824 году) в селении Буг близ Термеза. Это селение расположено на территории нынешнего Шерабадского района Сурхандарьинской области.' WHERE id = 2537;
UPDATE quiz_questions SET question_ru = 'Каков самый знаменитый труд ат-Термизи?', options_ru = '["«Аль-Джами ас-сахих» («Сунан ат-Термизи»)", "«Аль-Муватта»", "«Аль-Муджтаба»", "«Сахих Муслим»"]'::jsonb, explanation_ru = 'Труд «Аль-Джами ас-сахих» («Сунан ат-Термизи») он окончил в 270 году хиджры (884 году). Эта книга — один из шести самых достоверных сборников хадисов, «кутуб ситта». «Аль-Муватта» принадлежит Малику ибн Анасу, «Аль-Муджтаба» — ан-Насаи, «Сахих» — Имаму Муслиму.' WHERE id = 2538;
UPDATE quiz_questions SET question_ru = 'С какого возраста ат-Термизи отправился в дальние странствия за знанием?', options_ru = '["С 16 лет", "С 26 лет", "С 36 лет", "С 46 лет"]'::jsonb, explanation_ru = 'С 850 года, то есть с двадцати шести лет, он странствовал в Мекку, Медину, Ирак и города Хорасана и учился у знаменитых мухаддисов.' WHERE id = 2539;

-- ===== Burhoniddin Marg'inoniy =====
UPDATE quiz_questions SET question_ru = 'Каким своим трудом прославился Бурханиддин Маргинани в исламском мире?', options_ru = '["«Бабурнаме»", "«Хидоя»", "«Дивану лугат ат-турк»", "«Аль-Канун фит-тибб»"]'::jsonb, explanation_ru = 'Маргинани окончил труд «Хидоя» в 573 году хиджры (1178 году) в Самарканде. Эта книга стала главным учебником по ханафитскому фикху, преподаваемым в медресе.' WHERE id = 2543;
UPDATE quiz_questions SET question_ru = 'Где родился Бурханиддин Маргинани?', options_ru = '["В городе Самарканде", "В городе Бухаре", "В селении Риштан под Маргиланом", "В городе Ташкенте"]'::jsonb, explanation_ru = 'Учёный родился в 1123 году в селении Риштан под Маргиланом и получил первое образование на родине, в Риштане. Потому его нисбами были «ар-Риштани» и «аль-Маргинани».' WHERE id = 2544;
UPDATE quiz_questions SET question_ru = 'Где погребён Бурханиддин Маргинани?', options_ru = '["На самаркандском кладбище Чакардиза", "Подле святыни Пур Сиддик в Маргилане", "На древнем кладбище в Бухаре", "На кладбище в городе Багдаде"]'::jsonb, explanation_ru = 'Маргинани скончался 29 октября 1197 года в Самарканде и был погребён на кладбище Чакардиза. Абу Тахирходжа Самарканди описал место его могилы в труде «Самария».' WHERE id = 2545;

-- ===== Bahouddin Naqshband =====
UPDATE quiz_questions SET question_ru = 'В каком селении родился Бахауддин Накшбанд?', options_ru = '["В Касри Хиндуян (Касри Орифон)", "В Гиждуване", "В Ромитане", "В Шафиркане"]'::jsonb, explanation_ru = 'Он родился в 1318 году в селении Касри Хиндуян (Касри Орифон) под Бухарой. А Гиждуван — место, связанное с именем его наставника Абдулхалика Гиждувани.' WHERE id = 2549;
UPDATE quiz_questions SET question_ru = 'Каков главный девиз накшбандии?', options_ru = '["«Даст ба кору, дил ба ёр!»", "«Сперва подумай, потом скажи»", "«Терпение — золото»", "«Дил ба даст, ёр ба кор»"]'::jsonb, explanation_ru = 'Суть накшбандии выражена в девизе «Даст ба кору, дил ба ёр!» («Рука в труде, а сердце с Господом»).' WHERE id = 2550;
UPDATE quiz_questions SET question_ru = 'Сколько трудов по теории и практике суфизма написал Бахауддин Накшбанд?', options_ru = '["7", "10", "13", "20"]'::jsonb, explanation_ru = 'Он написал 13 трудов по теории и практике суфизма. Среди них особое значение имеют «Хаётнаме», «Далили ошикон», «Одоб ас-соликин».' WHERE id = 2551;

-- ===== Furqat =====
UPDATE quiz_questions SET question_ru = 'В какой газете работал Фуркат, приехав в Ташкент в 1889 году?', options_ru = '["«Садои Туркистон»", "«Туркистон вилоятининг газети»", "«Тараккий»", "«Хуршид»"]'::jsonb, explanation_ru = 'Фуркат приехал в Ташкент в июне 1889 года, работал в «Туркистон вилоятининг газети» и печатал в ней статьи, проповедующие науку и просвещение.' WHERE id = 2555;
UPDATE quiz_questions SET question_ru = 'В каком жанре написано произведение Фурката «Отпусти свою добычу, охотник»?', options_ru = '["Газель", "Рубаи", "Дастан", "Мусаддас"]'::jsonb, explanation_ru = '«Отпусти свою добычу, охотник» — знаменитый мусаддас Фурката, в котором поэт защищает право человека на вольную жизнь и решительно осуждает гнёт и произвол.' WHERE id = 2556;
UPDATE quiz_questions SET question_ru = 'В каком городе Фуркат провёл последние годы жизни?', options_ru = '["В Яркенде", "В Коканде", "В Ташкенте", "В Стамбуле"]'::jsonb, explanation_ru = 'С 1893 года Фуркат оседло жил в городе Яркенд в Восточном Туркестане и скончался там в 1909 году.' WHERE id = 2557;

-- ===== Abdulla Qahhor =====
UPDATE quiz_questions SET question_ru = 'В каком городе родился Абдулла Каххар?', options_ru = '["В Ташкенте", "В Коканде", "В Самарканде", "В Бухаре"]'::jsonb, explanation_ru = 'Абдулла Каххар родился 17 сентября 1907 года в городе Коканд.' WHERE id = 2558;
UPDATE quiz_questions SET question_ru = 'Какой роман Абдуллы Каххара написан в 1935 году?', options_ru = '["«Огни Кошчинара»", "«Мираж»", "«Синичка»", "«Сказки о былом»"]'::jsonb, explanation_ru = 'Роман «Мираж» написан в 1935 году. Роман «Огни Кошчинара» создан в 1951 году, а «Синичка» (1958) и «Сказки о былом» (1965) — повести.' WHERE id = 2559;
UPDATE quiz_questions SET question_ru = 'Произведения каких писателей перевёл Абдулла Каххар на узбекский язык?', options_ru = '["Пушкина, Толстого, Гоголя и Чехова", "Шекспира и Данте", "Сервантеса и Мольера", "Байрона и Гёте"]'::jsonb, explanation_ru = 'Абдулла Каххар мастерски перевёл на узбекский язык произведения А. С. Пушкина, Л. Толстого, Н. В. Гоголя и Чехова.' WHERE id = 2560;

-- ===== Chingiz Ahmarov =====
UPDATE quiz_questions SET question_ru = 'По мотивам какого произведения Чингиз Ахмаров выполнил в 1944–1947 годах росписи в фойе театра Навои?', options_ru = '["«Бабурнаме»", "«Хамсы» Навои", "Дастана «Алпамыш»", "«Шахнаме»"]'::jsonb, explanation_ru = 'Как указано в Национальной энциклопедии Узбекистана, он выполнил в фойе театра Навои монументальные росписи по мотивам «Хамсы» Навои (1944–1947).' WHERE id = 2613;
UPDATE quiz_questions SET question_ru = 'Стены какой станции Ташкентского метрополитена украшают работы Чингиза Ахмарова?', options_ru = '["«Пахтакор»", "«Космонавтов»", "«Алишер Навои»", "«Мустакиллик майдони»"]'::jsonb, explanation_ru = 'Как пишет энциклопедия, привлекательны его работы (80–90-е годы) на стенах станции «Алишер Навои» Ташкентского метрополитена и здания Музея прикладного искусства.' WHERE id = 2614;
UPDATE quiz_questions SET question_ru = 'В каком году Чингизу Ахмарову было присвоено звание народного художника Узбекистана?', options_ru = '["В 1942 году", "В 1958 году", "В 1964 году", "В 1982 году"]'::jsonb, explanation_ru = 'В энциклопедии отмечено, что Ахмаров Чингиз Габдурахманович удостоился звания народного художника Узбекистана в 1964 году.' WHERE id = 2615;

-- ===== Ibroyim Yusupov =====
UPDATE quiz_questions SET question_ru = 'Когда и где родился Ибрайим Юсупов?', options_ru = '["В 1935 году в городе Нукусе", "В 1929 году в селении Азад Чимбайского района", "В 1929 году в городе Ташкенте", "В 1924 году в городе Хиве"]'::jsonb, explanation_ru = 'Ибрайим Юсупов появился на свет в 1929 году в селении Азад Чимбайского района Каракалпакстана.' WHERE id = 2626;
UPDATE quiz_questions SET question_ru = 'Какое высокое звание было присвоено Ибрайиму Юсупову в 2004 году?', options_ru = '["Ветеран труда", "Народный наставник", "Герой Узбекистана", "Деятель науки"]'::jsonb, explanation_ru = 'В 2004 году поэту было присвоено звание Героя Узбекистана. А ранее, в 1975 году, он получил звание народного поэта Узбекистана и Каракалпакстана.' WHERE id = 2627;
UPDATE quiz_questions SET question_ru = 'С кем вместе Ибрайим Юсупов создал пьесу «Сорок девушек»?', options_ru = '["С Бердахом", "С Аметом Шамуратовым", "С Аджиниязом", "С Алишером Навои"]'::jsonb, explanation_ru = 'Пьеса «Сорок девушек» создана Ибрайимом Юсуповым вместе с Аметом Шамуратовым.' WHERE id = 2628;
